#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names_resolve_through_the_schema() {
        assert!(TYPES.windows(2).all(|pair| pair[0].0 < pair[1].0));
        assert_eq!(type_name(2001), Some("TSWP.StorageArchive"));
        assert_eq!(type_name(10000), Some("TP.DocumentArchive"));
        assert_eq!(type_name(999_999), None);
    }
}
